import sys
from collections import deque

def parse_grid(data, start_index):
    return [list(data[start_index]), list(data[start_index + 1])]

def serialize_grid(grid):
    return ''.join(grid[0] + grid[1])

def find_empty_position(grid):
    for i in range(2):
        for j in range(2):
            if grid[i][j] == 'X':
                return i, j

def get_neighbors(x, y):
    neighbors = []
    if x > 0: neighbors.append((x - 1, y)) # up
    if x < 1: neighbors.append((x + 1, y)) # down
    if y > 0: neighbors.append((x, y - 1)) # left
    if y < 1: neighbors.append((x, y + 1)) # right
    return neighbors

def is_solvable(initial_grid, target_grid):
    start = serialize_grid(initial_grid)
    target = serialize_grid(target_grid)

    if start == target:
        return True

    queue = deque([initial_grid])
    visited = set()
    visited.add(start)

    while queue:
        current_grid = queue.popleft()
        x, y = find_empty_position(current_grid)

        for nx, ny in get_neighbors(x, y):
            new_grid = [row[:] for row in current_grid]
            # Swap empty space with neighbor
            new_grid[x][y], new_grid[nx][ny] = new_grid[nx][ny], new_grid[x][y]
            serialized = serialize_grid(new_grid)

            if serialized == target:
                return True

            if serialized not in visited:
                visited.add(serialized)
                queue.append(new_grid)

    return False

input = sys.stdin.read
data = input().split()
bessie_grid = parse_grid(data, 0)
elsie_grid = parse_grid(data, 2)

if is_solvable(bessie_grid, elsie_grid):
    print("YES")
else:
    print("NO")

